(function(){
  function parse(qs){
    qs=String(qs==null?'':qs).replace(/^\?/,'');
    var out={}; if(qs==='') return {value:out};
    qs.split('&').forEach(function(pair){ if(pair==='')return; var i=pair.indexOf('='); var k,v;
      if(i<0){k=pair;v='';} else {k=pair.slice(0,i);v=pair.slice(i+1);}
      k=decodeURIComponent(k.replace(/\+/g,' ')); v=decodeURIComponent(v.replace(/\+/g,' '));
      if(out.hasOwnProperty(k)){ if(!Array.isArray(out[k])) out[k]=[out[k]]; out[k].push(v); } else out[k]=v; });
    return {value:out};
  }
  function build(obj){
    if(obj==null||typeof obj!=='object') return {error:'需为对象'};
    var parts=[];
    Object.keys(obj).forEach(function(k){ var v=obj[k];
      if(Array.isArray(v)) v.forEach(function(x){ parts.push(encodeURIComponent(k)+'='+encodeURIComponent(x)); });
      else parts.push(encodeURIComponent(k)+'='+encodeURIComponent(v)); });
    return {value:parts.join('&')};
  }
  function sort(qs){ var o=parse(qs).value; var keys=Object.keys(o).sort(); var parts=[];
    keys.forEach(function(k){ var v=o[k]; if(Array.isArray(v)) v.forEach(function(x){parts.push(encodeURIComponent(k)+'='+encodeURIComponent(x));}); else parts.push(encodeURIComponent(k)+'='+encodeURIComponent(v)); });
    return {value:parts.join('&')}; }
  var API={parse:parse,build:build,sort:sort};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__QuerystringForge__=API;
})();
